function createConcern(reason:string){if(ref.current.incidents.some(i=>i.status!=='resolved')){setModal('incident');return;}const t=ref.current.trips.find(t=>t.status==='active')||null;const i=makeIncident(t,'concern',reason);mutate(s=>({...s,incidents:[i,...s.incidents],trips:s.trips.map(x=>x.id===t?.id?recordEvent(x,'concern',reason):x)}));setModal('incident');if(ref.current.settings.notifications&&'Notification'in window&&Notification.permission==='granted')new Notification('RakshaTrack safety check',{body:'Please confirm your safety.',icon:'/favicon.svg'});}
